import math
import numbers


def _finite_real(value):
    return not isinstance(value, bool) and isinstance(value, numbers.Real) and math.isfinite(value)


def solve_chain(stiffness, loads, left, right, tolerance=1e-10, max_iterations=10000):
    k = list(stiffness)
    f = list(loads)
    if len(k) != len(f) + 1:
        raise ValueError("invalid stiffness length")
    if not all(_finite_real(value) and value > 0 for value in k):
        raise ValueError("stiffness values must be positive and finite")
    if not all(_finite_real(value) for value in f + [left, right]):
        raise ValueError("values must be finite real numbers")
    if not _finite_real(tolerance) or tolerance <= 0:
        raise ValueError("invalid tolerance")
    if isinstance(max_iterations, bool) or not isinstance(max_iterations, int) or max_iterations <= 0:
        raise ValueError("invalid iteration limit")
    if not f:
        return (left, right)

    values = [0.0] * len(f)
    for _ in range(max_iterations):
        largest = 0.0
        for i, load in enumerate(f):
            previous = left if i == 0 else values[i - 1]
            following = 0.0 if i == len(f) - 1 else values[i + 1]
            updated = (load + k[i] * previous + k[i + 1] * following) / (k[i] + k[i + 1])
            largest = max(largest, abs(updated - values[i]))
            values[i] = updated
        if largest <= tolerance:
            return (left, *values, right)
    raise ValueError("iteration did not converge")

